"""The terminal's benchmarks: cpu-z, gpu-z and spec.

All three measure on the device, now, through native code compiled into the
app — CodeBench/Bench/*.c for the CPU (reached through ctypes.CDLL(None),
which releases the GIL for every call, so N threads are N cores) and
CodeBench/GPUBench.swift for the GPU (Metal, timed by the GPU itself). In a
build without those entry points cpu-z and gpu-z fall back to the shell's
older Python measurements (offlinai_shell._cpuz_legacy / _gpuz_legacy).

`spec` runs CodeBench's own workloads of the kinds SPEC CPU 2017 and SPEC CPU
2026 are made of. It is not SPEC: none of SPEC's code, inputs or reference
times are in it, and its ratios are not SPEC results.
"""

import ctypes
import json
import math
import os
import platform
import sys
import threading
import time

# ── The native entry points ─────────────────────────────────────────────


class _Result(ctypes.Structure):
    """cb_bench_result (CodeBench/Bench/cb_bench.h)."""
    _fields_ = [("checksum", ctypes.c_uint64), ("value", ctypes.c_double),
                ("work", ctypes.c_double), ("unit", ctypes.c_char_p)]


_NATIVE = None


def native():
    """The app's benchmark functions, or None in a build without them."""
    global _NATIVE
    if _NATIVE is not None:
        return _NATIVE or None
    try:
        lib = ctypes.CDLL(None)
        lib.cb_spec_count.restype = ctypes.c_int
        lib.cb_spec_id.restype = ctypes.c_char_p
        lib.cb_spec_id.argtypes = [ctypes.c_int]
        lib.cb_spec_run.restype = ctypes.c_int
        lib.cb_spec_run.argtypes = [ctypes.c_char_p, ctypes.c_int, ctypes.POINTER(_Result)]
        lib.cb_cpu_clock_ghz.restype = ctypes.c_double
        lib.cb_cpu_clock_ghz.argtypes = [ctypes.c_int]
        lib.cb_cpu_fma_gflops.restype = ctypes.c_double
        lib.cb_cpu_fma_gflops.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_cpu_triad_gbs.restype = ctypes.c_double
        lib.cb_cpu_triad_gbs.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_cpu_latency_ns.restype = ctypes.c_double
        lib.cb_cpu_latency_ns.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_info_json.restype = ctypes.c_int
        lib.cb_gpu_info_json.argtypes = [ctypes.c_char_p, ctypes.c_int]
        lib.cb_gpu_fma_tflops.restype = ctypes.c_double
        lib.cb_gpu_fma_tflops.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_bandwidth_gbs.restype = ctypes.c_double
        lib.cb_gpu_bandwidth_gbs.argtypes = [ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_matmul_gflops.restype = ctypes.c_double
        lib.cb_gpu_matmul_gflops.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
        lib.cb_gpu_blur_mpix.restype = ctypes.c_double
        lib.cb_gpu_blur_mpix.argtypes = [ctypes.c_int]
    except (OSError, AttributeError):
        _NATIVE = False
        return None
    _NATIVE = lib
    return lib


# QoS classes (sys/qos.h), and Darwin's background band (sys/resource.h).
_QOS_USER_INTERACTIVE = 0x21
_PRIO_DARWIN_PROCESS = 4
_PRIO_DARWIN_BG = 0x1000

# The kind of core the benchmark in progress runs on: None (the scheduler's
# choice, performance cores first), "p" or "e". Set by _OnCores, which also
# keeps the run's _Placement here.
_CORE = None
_PLACEMENT = None
_INFO_CACHE = None


class _Boost:
    """The calling thread at user-interactive QoS while a benchmark runs, and
    back to what it was after. The terminal runs commands on a thread whose
    QoS lets the scheduler put it on an efficiency core: measured in the app
    on an M4, cpu-z's single-core work took 1.5 times as long there. On the
    efficiency cores (`--core e`) it leaves the thread as it is."""

    def __enter__(self):
        self.prev = None
        if _CORE == "e":
            return self
        try:
            libc = ctypes.CDLL(None)
            self.prev = libc.qos_class_self()
            libc.pthread_set_qos_class_self_np(_QOS_USER_INTERACTIVE, 0)
        except Exception:
            pass
        return self

    def __exit__(self, *exc):
        if self.prev:
            try:
                ctypes.CDLL(None).pthread_set_qos_class_self_np(self.prev, 0)
            except Exception:
                pass
        return False


def _core_option(argv):
    """`--core p|e` from argv: "p", "e", None when absent; ValueError if neither."""
    value = _option(argv, "--core")
    if value is None:
        return None
    kind = {"p": "p", "perf": "p", "performance": "p",
            "e": "e", "eff": "e", "efficiency": "e"}.get(value.lower())
    if kind is None:
        raise ValueError(f"--core takes p (performance) or e (efficiency), not {value!r}")
    return kind


class _OnCores:
    """Runs what is inside on one kind of core, and keeps count of where it
    really ran (_Placement).

    Darwin gives an app no way to pin a thread to a core, and measured on an
    M4 (macOS 27) only one request is binding:
    - "e": the app goes into Darwin's background band until the end. That
      kept every thread on the efficiency cores (0% of the time on the
      others) — but the band also holds the efficiency cores below their
      normal clock (1.4–2.5 GHz measured, against about 2.9). Nothing else
      keeps work off the performance cores: a background-QoS thread, with
      or without the thread-level band, a background task role or the
      performance cores kept busy, still spent 20–100% of its time on them.
    - "p" (and no --core): each benchmark thread at user-interactive QoS
      (_Boost). That asks for the performance cores but does not hold them:
      four threads on a busy M4 spent 5–20% of their time on the efficiency
      cores. So the run reports how much it got."""

    def __init__(self, kind):
        self.kind = kind
        self.ok = True
        self.placement = None

    def __enter__(self):
        global _CORE, _PLACEMENT
        self.prev = _CORE, _PLACEMENT
        _CORE = self.kind
        if self.kind == "e":
            try:
                self.ok = ctypes.CDLL(None).setpriority(_PRIO_DARWIN_PROCESS, 0, _PRIO_DARWIN_BG) == 0
            except Exception:
                self.ok = False
        self.placement = _Placement()
        _PLACEMENT = self.placement
        return self

    def __exit__(self, *exc):
        global _CORE, _PLACEMENT
        if self.kind == "e":
            try:
                ctypes.CDLL(None).setpriority(_PRIO_DARWIN_PROCESS, 0, 0)
            except Exception:
                pass
        _CORE, _PLACEMENT = self.prev
        return False


def _core_count(info, kind):
    """How many cores of `kind` (None: all of them)."""
    if kind == "p" and info.get("p_cores"):
        return info["p_cores"]
    if kind == "e" and info.get("e_cores"):
        return info["e_cores"]
    return info["cores"]


def _core_name(kind, n=1, info=None):
    """"performance core(s)", "efficiency core(s)" — or what the kernel calls
    the chip's fastest and slowest kinds (hw.perflevelN.name), on a chip
    where those differ."""
    info = info or _INFO_CACHE or {}
    name = {"p": info.get("p_name", "performance"), "e": info.get("e_name", "efficiency")}.get(kind)
    return (f"{name} core" if name else "core") + ("s" if n != 1 else "")


# ── Where the work ran ─────────────────────────────────────────────────

class _RUsage(ctypes.Structure):
    """struct rusage_info_v6 (sys/resource.h), as far as the fields read."""
    _fields_ = [("uuid", ctypes.c_uint8 * 16)] + [(n, ctypes.c_uint64) for n in (
        "user_time", "system_time", "pkg_idle_wkups", "interrupt_wkups", "pageins", "wired_size",
        "resident_size", "phys_footprint", "proc_start_abstime", "proc_exit_abstime", "child_user_time",
        "child_system_time", "child_pkg_idle_wkups", "child_interrupt_wkups", "child_pageins",
        "child_elapsed_abstime", "diskio_bytesread", "diskio_byteswritten", "cpu_time_qos_default",
        "cpu_time_qos_maintenance", "cpu_time_qos_background", "cpu_time_qos_utility",
        "cpu_time_qos_legacy", "cpu_time_qos_user_initiated", "cpu_time_qos_user_interactive",
        "billed_system_time", "serviced_system_time", "logical_writes", "lifetime_max_phys_footprint",
        "instructions", "cycles", "billed_energy", "serviced_energy", "interval_max_phys_footprint",
        "runnable_time", "flags", "user_ptime", "system_ptime", "pinstructions", "pcycles")] + [
        ("rest", ctypes.c_uint64 * 24)]


class _Timebase(ctypes.Structure):
    _fields_ = [("numer", ctypes.c_uint32), ("denom", ctypes.c_uint32)]


def _usage():
    """(CPU time, of it on the performance cores — both in ns —, cycles,
    of them on the performance cores) for the whole app so far, from the
    kernel's own per-cluster accounting; None where it is not available."""
    try:
        libc = ctypes.CDLL(None)
        r = _RUsage()
        if libc.proc_pid_rusage(os.getpid(), 6, ctypes.byref(r)) != 0:    # RUSAGE_INFO_V6
            return None
        tb = _Timebase()
        libc.mach_timebase_info(ctypes.byref(tb))
        k = tb.numer / tb.denom if tb.denom else 1.0
        return ((r.user_time + r.system_time) * k, (r.user_ptime + r.system_ptime) * k,
                r.cycles, r.pcycles)
    except Exception:
        return None


class _Placement:
    """How a stretch of work divided between the kinds of core, and the
    clock each kind ran at (cycles over time), measured by the kernel
    rather than assumed. The figures are the app's, so its other threads
    count too; while a benchmark runs they are nearly idle."""

    def __init__(self):
        self.start = _usage()

    def result(self):
        end = _usage()
        if not self.start or not end:
            return None
        t, tp = end[0] - self.start[0], end[1] - self.start[1]
        c, cp = end[2] - self.start[2], end[3] - self.start[3]
        if t <= 0:
            return None
        te, ce = t - tp, c - cp
        return {"p_share": tp / t,
                "p_ghz": cp / tp if tp > t * 1e-3 else None,
                "e_ghz": ce / te if te > t * 1e-3 else None}

    def line(self, kind, info=None):
        """One line for the end of a run: where it ran, and how fast."""
        r = self.result()
        if not r:
            return None
        ps, es = r["p_share"], 1.0 - r["p_share"]
        pn, en = _core_name("p", 2, info), _core_name("e", 2, info)
        bits = []
        if ps >= 0.0005:
            bits.append(f"{pn} {ps * 100:.0f}%" + (f" at {r['p_ghz']:.2f} GHz" if r["p_ghz"] else ""))
        if es >= 0.0005:
            bits.append(f"{en} {es * 100:.0f}%" + (f" at {r['e_ghz']:.2f} GHz" if r["e_ghz"] else ""))
        text = "ran on " + ", ".join(bits)
        if kind == "p" and ps < 0.995:
            text += f" — the system lends an app its {pn}, it does not reserve them"
        elif kind == "e":
            text += " — the background band, the one way an app can stay off the faster cores, " \
                    "keeps these below their normal clock"
        return text, r


def _columns():
    try:
        import shutil
        return shutil.get_terminal_size().columns
    except Exception:
        return 80


def run_workload(lib, wid, size):
    """One copy of workload `wid` at `size`: (seconds, result) or (None, code)."""
    out = _Result()
    t0 = time.perf_counter()
    rc = lib.cb_spec_run(wid.encode(), size, ctypes.byref(out))
    dt = time.perf_counter() - t0
    return (dt, out) if rc == 0 else (None, rc)


def run_copies(lib, wid, size, copies):
    """`copies` copies of `wid` at once, one thread each: the wall time
    until the last ends, and every copy's result."""
    results = [None] * copies
    gate = threading.Barrier(copies + 1)

    def one(k):
        with _Boost():
            gate.wait()
            results[k] = run_workload(lib, wid, size)

    threads = [threading.Thread(target=one, args=(k,), daemon=True) for k in range(copies)]
    for t in threads:
        t.start()
    gate.wait()
    t0 = time.perf_counter()
    for t in threads:
        t.join()
    return time.perf_counter() - t0, results


# ── The device ──────────────────────────────────────────────────────────


def sysctl(name, text=False):
    """A sysctl by name, as an int (or a string), or None."""
    try:
        libc = ctypes.CDLL(None)
        size = ctypes.c_size_t(0)
        key = name.encode()
        if libc.sysctlbyname(key, None, ctypes.byref(size), None, 0) != 0 or size.value == 0:
            return None
        buf = ctypes.create_string_buffer(size.value)
        if libc.sysctlbyname(key, buf, ctypes.byref(size), None, 0) != 0:
            return None
        if text:
            return buf.value.decode(errors="replace")
        return int.from_bytes(buf.raw[:size.value], "little")
    except Exception:
        return None


# The Arm features worth naming, as the kernel reports them
# (hw.optional.arm.FEAT_*), in the order an architecture manual lists them.
_ARM_FEATURES = ["AES", "PMULL", "SHA1", "SHA256", "SHA512", "SHA3", "CRC32", "LSE", "LSE2",
                 "RDM", "FP16", "FHM", "DotProd", "I8MM", "BF16", "EBF16", "FCMA", "JSCVT",
                 "FRINTTS", "LRCPC", "LRCPC2", "DPB", "DPB2", "SB", "SSBS", "BTI", "PAuth",
                 "PAuth2", "CSSC", "WFxT", "AFP", "RPRES", "SME", "SME2", "SME_F64F64",
                 "SME_I16I64", "SVE"]


def cpu_info():
    """What the kernel says about the cores, caches, memory and features."""
    info = {"cores": os.cpu_count() or 0}
    # perflevel0 is the fastest kind of core and the last level the slowest;
    # their names come from the kernel ("Performance", "Efficiency" — a chip
    # whose kinds are called otherwise is labelled as it calls them).
    levels = sysctl("hw.nperflevels") or 0
    p = sysctl("hw.perflevel0.physicalcpu")
    e = sysctl(f"hw.perflevel{levels - 1}.physicalcpu") if levels >= 2 else 0
    if p:
        info["p_cores"] = p
        info["e_cores"] = e or 0
        info["p_name"] = (sysctl("hw.perflevel0.name", text=True) or "Performance").lower()
        if levels >= 2:
            info["e_name"] = (sysctl(f"hw.perflevel{levels - 1}.name", text=True) or "Efficiency").lower()
    for level, key in (("perflevel0", "p"), (f"perflevel{max(levels - 1, 1)}", "e")):
        for cache in ("l1icachesize", "l1dcachesize", "l2cachesize"):
            v = sysctl(f"hw.{level}.{cache}")
            if v:
                info[f"{key}_{cache}"] = v
    for key, name in (("line", "hw.cachelinesize"), ("page", "hw.pagesize"),
                      ("memory", "hw.memsize")):
        v = sysctl(name)
        if v:
            info[key] = v
    feats = [f for f in _ARM_FEATURES if sysctl(f"hw.optional.arm.FEAT_{f}") == 1]
    if feats:
        info["features"] = feats
    global _INFO_CACHE
    _INFO_CACHE = info
    return info


def device_line():
    """("iPad Air 11-inch (M3)", "Apple M3"), from the shell's table."""
    try:
        from offlinai_shell import _apple_device_info
        return _apple_device_info()
    except Exception:
        return platform.machine(), "unknown chip"


def _kb(n):
    return f"{n // (1 << 20)} MB" if n >= (1 << 20) else f"{n // 1024} KB"


def _colors():
    from offlinai_shell import BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET
    return BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET


def _bar(frac, width=24):
    _, DIM, _, GRN, _, _, _, RESET = _colors()
    n = max(0, min(width, int(round(frac * width))))
    return f"{GRN}{'█' * n}{DIM}{'░' * (width - n)}{RESET}"


def _status(text):
    sys.stdout.write(f"\r  {text}\033[K")
    sys.stdout.flush()


# Where results are saved: in the Workspace, so My work and the Files app
# list them (they show only what is under ~/Documents/Workspace).
_RESULTS_DIR = "~/Documents/Workspace/Benchmarks"


def _results_dir():
    root = os.path.expanduser(_RESULTS_DIR)
    os.makedirs(root, exist_ok=True)
    return root


def _save_json(kind, data, path=None):
    """Writes `data` to `path`, or to Workspace/Benchmarks/<kind>-<time>.json."""
    if not path:
        path = os.path.join(_results_dir(), f"{kind}-{time.strftime('%Y-%m-%d-%H%M%S')}.json")
    with open(path, "w") as f:
        json.dump(data, f, indent=2, sort_keys=True)
    return path


def _option(argv, name, default=None):
    """`--name value` or `--name=value` from argv."""
    for i, a in enumerate(argv):
        if a == name and i + 1 < len(argv) and not argv[i + 1].startswith("-"):
            return argv[i + 1]
        if a.startswith(name + "="):
            return a.split("=", 1)[1]
    return default


def _si(x):
    """1234567 -> '1.23 M', for a throughput column."""
    for scale, prefix in ((1e9, "G"), (1e6, "M"), (1e3, "k")):
        if x >= scale:
            return f"{x / scale:.2f} {prefix}"
    return f"{x:.1f}"


def _geomean(values):
    values = [v for v in values if v and v > 0]
    return math.exp(sum(math.log(v) for v in values) / len(values)) if values else 0.0


def _run_on_cores(fn, sh, argv, command):
    """`fn(sh, argv)` on the kind of core `--core` asks for (see _OnCores)."""
    try:
        kind = _core_option(argv)
    except ValueError as e:
        _, _, RED, _, _, _, _, RESET = _colors()
        print(f"{RED}{command}:{RESET} {e}")
        return
    with _OnCores(kind) as on, _Boost():
        if not on.ok:
            _, DIM, _, _, YLW, _, _, RESET = _colors()
            print(f"{YLW}{command}:{RESET} this system wouldn't keep the app on its efficiency "
                  f"cores {DIM}— running where the scheduler puts it{RESET}")
        return fn(sh, argv)


# ── graphs ──────────────────────────────────────────────────────────────

_GRAPH_FORMATS = ("html", "png", "jpg", "jpeg", "svg", "pdf")


def _short(path):
    """`~/Documents/…` rather than the container path (on a Mac it names
    the user); the app's result-line reader expands the `~` again."""
    home = os.path.expanduser("~")
    for p, h in ((path, home), (os.path.realpath(path), os.path.realpath(home))):
        if h and p.startswith(h + os.sep):
            return "~" + p[len(h):]
    return path


def _graph_path(kind, argv):
    """--out as a format (html, png, jpg, svg, pdf) or a file; by default
    an HTML page in Workspace/Benchmarks."""
    out = _option(argv, "--out") or "html"
    fmt = out.lower().lstrip(".")
    if fmt in _GRAPH_FORMATS:
        return os.path.join(_results_dir(), f"{kind}-{time.strftime('%Y-%m-%d-%H%M%S')}.{fmt}")
    path = os.path.abspath(os.path.expanduser(out))
    if os.path.splitext(path)[1].lower().lstrip(".") not in _GRAPH_FORMATS:
        path += ".html"
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return path


